  if (typeof value === 'string') {
    return !Number.isNaN(Date.parse(value));
  }
  return typeof value === 'number' && Number.isFinite(new Date(value).getTime());
}

function isValidSessionId(value: unknown): value is string {
  return typeof value === 'string' && value.length >= 1 && value.length <= MAX_SESSION_ID_LENGTH;
}

function validateBefore(before: unknown): ValidationResult | NonNullable<ListSessionsMessage['before']> {
  if (typeof before !== 'object' || before === null) {
    return {valid: false, error: 'list_sessions before must be an object'};
  }
  const {updatedAt, sessionId} = before as Record<string, unknown>;
  if (!isValidSessionId(sessionId)) {
    return {valid: false, error: `list_sessions before.sessionId must be 1-${MAX_SESSION_ID_LENGTH} characters`};
  }
  if (!isDateValue(updatedAt)) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a date string or number'};
  }
  return {updatedAt: updatedAt as string | number, sessionId};
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const frame: ListSessionsMessage = {type: 'list_sessions'};

  const {limit} = message;
  if (limit !== undefined && !(typeof limit === 'number' && Number.isInteger(limit) && limit >= 0)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }
  if (limit !== undefined) {
    frame.limit = limit;
  }

  if (message.before === undefined) {
    return {valid: true, data: frame};
  }
  const before = validateBefore(message.before);
  if ('valid' in before) {
    return before;
  }
  frame.before = before;
  return {valid: true, data: frame};
}
